  <article className="edit-info-card"><div className="edit-info-main"><span className="edit-dumbbell">✣</span><label>Workout Name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Name your workout" maxLength={60}/></label></div><div className="edit-stats"><span><b>▱</b>{ids.length} Exercises</span><span><b>◷</b>~ {minutes} min</span><span><b>♨</b>~ {calories} kcal</span></div></article>
