  <div className="planned-exercises">{ids.map((id,index)=>{const e=get(id);if(!e)return null;return <article className="edit-exercise-card" key={id}>{reorder&&<div className="edit-move-controls"><button disabled={index===0} onClick={()=>move(index,-1)} aria-label={`Move ${e.name} up`}>⌃</button><button disabled={index===ids.length-1} onClick={()=>move(index,1)} aria-label={`Move ${e.name} down`}>⌄</button></div>}<Image src={e.image}/><span className="edit-exercise-copy"><b>{e.name}</b><small>{e.muscle} · {e.equipment}</small></span><span className="edit-reps">{e.sets||3} Sets × {e.reps||10} {e.muscle==='Abs'?'sec':'Reps'}</span><button className="remove" onClick={()=>toggle(id)} aria-label={`Remove ${e.name}`}>▤</button></article>})}</div>
