  <div id="edit-library" className="edit-library"><label className="edit-search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search 100+ exercises..."/><span className="edit-filter-icon">☷</span></label><div className="edit-muscle-filters">{muscles.map(item=><button className={muscle===item?'active':''} onClick={()=>setMuscle(item)} key={item}>{item}</button>)}</div><div className="available-exercises">{rows.map(e=>{const selected=ids.includes(e.id);return <article className="edit-exercise-card available" key={e.id}><span className="edit-drag-mark">⠿</span><Image src={e.image}/><span className="edit-exercise-copy"><b>{e.name}</b><small>{e.muscle} · {e.equipment}</small></span><button className={selected?'edit-added':'edit-add-button'} onClick={()=>toggle(e.id)}>{selected?'✓ Added':'＋ Add'}</button></article>})}</div></div>
