function Settings({go}){let[updating,setUpdating]=useState(false),[updateMessage,setUpdateMessage]=useState('');let updateApp=async()=>{if(updating)return;setUpdating(true);setUpdateMessage('Checking for the latest version…');try{let registration=await navigator.serviceWorker?.getRegistration();if(registration)await registration.update();setUpdateMessage('Refreshing RK FITNESS…');setTimeout(()=>window.location.reload(),500)}catch(error){console.error('RK FITNESS update check failed',error);setUpdateMessage('Update check failed. Try again when you are online.');setUpdating(false)}};return <section><Top title="Settings" back={()=>go('me')}/><h3>App</h3><button className="menu update-app-button" disabled={updating} onClick={updateApp}>{updating?'Checking for updates…':'Update App'}<b>{updating?'↻':'↻'}</b></button>{updateMessage&&<p className="update-app-message" role="status">{updateMessage}</p>}<h3>Account</h3><button className="menu" onClick={async()=>{await supabase.auth.signOut();go('welcome')}}>Log out <b>›</b></button><h3>Local app data</h3><button className="menu" onClick={()=>{localStorage.removeItem(storageKey(localStorage.getItem(ACTIVE_USER_KEY)||''));location.reload()}}>Reset device data <b>›</b></button></section>}
class AppErrorBoundary extends React.Component {
 constructor(props){super(props);this.state={hasError:false};}
 static getDerivedStateFromError(){return {hasError:true};}
 componentDidCatch(error,info){console.error('RK FITNESS screen render failed',error,info);}
 render(){if(this.state.hasError)return <main style={{minHeight:'100dvh',display:'grid',placeContent:'center',gap:16,padding:24,background:'#050805',color:'#fff',textAlign:'center'}}><h1 style={{color:'#b7ff00'}}>Unable to open this screen</h1><p>Please reload RK FITNESS. Your saved workout data is kept.</p><button onClick={()=>location.reload()} style={{padding:'14px 22px',border:0,borderRadius:12,background:'#b7ff00',color:'#050805',fontWeight:800}}>Reload app</button></main>;return this.props.children;}
}
createRoot(document.getElementById('root')).render(<AppErrorBoundary><App/></AppErrorBoundary>);
